"""Money helpers: all prices are handled as integer cents."""


def to_cents(price):
    """Convert a price string such as '19.99' to integer cents."""
    return int(float(price) * 100)


def format_cents(cents):
    return "$%d.%02d" % (cents // 100, cents % 100)

files.shop/pricing.py:
def apply_discount(cents, percent):
    """Integer cents after a percentage discount (rounded down)."""
    return cents * (100 - percent) // 100

