from shop.money import to_cents
from shop.pricing import apply_discount


class Cart:
    def __init__(self):
        self.items = []

    def add(self, name, price, qty=1):
        self.items.append((name, to_cents(price), qty))

    def subtotal(self):
        return sum(cents * qty for _, cents, qty in self.items)

    def total(self, discount_percent=0):
        return apply_discount(self.subtotal(), discount_percent)

